// Method-level fixtures for the mutable three-compatible math layer (`@aura3d/math/three`).
//
// Every public method (and accessor) of Vector2/3/4, Matrix3/4, Quaternion, Euler, Color, Box3,
// Sphere, Plane, Ray, Frustum and Triangle gets a case named `Class#method`. A case runs the SAME
// source against real three.js r185 (goldens.json, generated by generate.mjs) and against the
// Aura3D compat classes (tests/unit/math/three-compat-parity.test.ts). A case serialises, for each
// scenario: whether the call returned its receiver (`this`), the receiver after the call, the
// returned value when it is not the receiver, and every object argument after the call (so `target`
// out-parameters and aliasing are covered). Thrown errors serialise their message.
//
// Non-finite numbers cannot live in JSON, so `ser` maps NaN and +/-Infinity to sentinel values.

const NAN_CODE = 1234567.125;
const PINF_CODE = 9e15;
const NINF_CODE = -9e15;
const NULL_CODE = -4242.5;
const UNDEFINED_CODE = -4243.5;
const THROWN_CODE = -5555;

const num = (n) => (n === undefined ? UNDEFINED_CODE : Number.isNaN(n) ? NAN_CODE : n === Infinity ? PINF_CODE : n === -Infinity ? NINF_CODE : n);

export const ser = (v, depth = 0) => {
  if (v === null) return [NULL_CODE];
  if (v === undefined) return [UNDEFINED_CODE];
  if (typeof v === "number") return [num(v)];
  if (typeof v === "boolean") return [v ? 1 : 0];
  if (typeof v === "string") return [v.length, ...Array.from(v, (c) => c.charCodeAt(0))];
  if (typeof v === "function") return [];
  if (depth > 6) return [];
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return [v.length, ...Array.from(v).flatMap((x) => ser(x, depth + 1))];
  if (typeof v !== "object") return [];
  if ("elements" in v) return Array.from(v.elements, num);
  if ("planes" in v) return v.planes.flatMap((p) => ser(p, depth + 1));
  if ("center" in v && "radius" in v && !("a" in v)) return [...ser(v.center, depth + 1), num(v.radius)];
  if ("normal" in v && "constant" in v) return [...ser(v.normal, depth + 1), num(v.constant)];
  if ("origin" in v && "direction" in v) return [...ser(v.origin, depth + 1), ...ser(v.direction, depth + 1)];
  // Vector2/3/4 have min()/max() methods, so a box is recognised by object-valued corners
  if (typeof v.min === "object" && v.min !== null && typeof v.max === "object" && v.max !== null && !Array.isArray(v.min)) return [...ser(v.min, depth + 1), ...ser(v.max, depth + 1)];
  if ("a" in v && "b" in v && "c" in v) return [...ser(v.a, depth + 1), ...ser(v.b, depth + 1), ...ser(v.c, depth + 1)];
  if ("order" in v && "x" in v) return [num(v.x), num(v.y), num(v.z), ...ser(v.order)];
  if ("w" in v && "x" in v) return [num(v.x), num(v.y), num(v.z), num(v.w)];
  if ("z" in v && "x" in v) return [num(v.x), num(v.y), num(v.z)];
  if ("y" in v && "x" in v) return [num(v.x), num(v.y)];
  if ("r" in v && "g" in v && "b" in v) return [num(v.r), num(v.g), num(v.b)];
  return Object.keys(v).sort().flatMap((k) => ser(v[k], depth + 1));
};

const serArg = (a) => (a !== null && typeof a === "object" ? ser(a) : []);

/** Call `receiver[method](...args)` and serialise the outcome (see file header). */
const run = (L, receiver, method, argsOf) => {
  let args = [];
  // warnings (bad colour names, unknown Euler orders, r185 deprecations) are part of the observable behaviour
  const originalWarn = console.warn;
  let warnings = 0;
  console.warn = () => { warnings += 1; };
  try {
    args = argsOf(L, receiver);
    const ret = receiver[method](...args);
    return [ret === receiver ? 1 : 0, ...ser(receiver), ...(ret === receiver ? [] : ser(ret)), ...args.flatMap(serArg), warnings];
  } catch (error) {
    return [THROWN_CODE, ...ser(String(error.message)), ...ser(receiver), warnings];
  } finally {
    console.warn = originalWarn;
  }
};

/** Run `fn` with Math.random replaced by a seeded generator, so random() methods compare exact values. */
const withSeededRandom = (seed, fn) => {
  const original = Math.random;
  Math.random = prng(seed);
  try {
    return fn();
  } finally {
    Math.random = original;
  }
};

const A = (...items) => (L, r) => items.map((item) => (typeof item === "function" ? item(L, r) : item));
const SELF = (L, r) => r;

// builders (lazy: they take the library `L`)
const v2 = (x, y) => (L) => new L.Vector2(x, y);
const v3 = (x, y, z) => (L) => new L.Vector3(x, y, z);
const unit = (x, y, z) => (L) => new L.Vector3(x, y, z).normalize();
const v4 = (x, y, z, w) => (L) => new L.Vector4(x, y, z, w);
const quat = (x, y, z, w) => (L) => new L.Quaternion(x, y, z, w);
const eul = (x, y, z, order) => (L) => new L.Euler(x, y, z, order);
const arr = (...values) => () => [...values];
const m3 = (...e) => (L) => new L.Matrix3().set(...e);
const m4 = (...e) => (L) => new L.Matrix4().set(...e);
const col = (r, g, b) => (L) => new L.Color().setRGB(r, g, b);
const box = (a, b, c, d, e, f) => (L) => new L.Box3(new L.Vector3(a, b, c), new L.Vector3(d, e, f));
const sph = (x, y, z, r) => (L) => new L.Sphere(new L.Vector3(x, y, z), r);
const pln = (x, y, z, c) => (L) => new L.Plane(new L.Vector3(x, y, z), c);
const tri = (a, b, c) => (L) => new L.Triangle(new L.Vector3(...a), new L.Vector3(...b), new L.Vector3(...c));
const q1 = (L) => new L.Quaternion().setFromAxisAngle(new L.Vector3(0, 1, 0), 0.9);
const q2 = (L) => new L.Quaternion().setFromEuler(new L.Euler(0.3, -0.4, 1.1, "XYZ"));
const m3a = m3(2, 0.5, 0, -1, 3, 0.25, 0.1, 0, 1.5);
const m3b = m3(1, 2, 3, 0, 1, 4, 5, 6, 0);
const m4a = (L) => new L.Matrix4().compose(new L.Vector3(1, -2, 3), q2(L), new L.Vector3(2, 0.5, 1.5));
const m4b = (L) => new L.Matrix4().makeRotationAxis(new L.Vector3(1, 1, 0).normalize(), 0.8).setPosition(0.5, -1, 2);
const m4p = (L) => new L.Matrix4().makePerspective(-1, 1, 0.75, -0.75, 0.1, 100);
const m4mirror = (L) => new L.Matrix4().makeScale(-1, 2, 0.5);
const attr = () => ({
  count: 3,
  getX: (i) => 10 * i + 1,
  getY: (i) => 10 * i + 2,
  getZ: (i) => 10 * i + 3,
  getW: (i) => 10 * i + 4,
});
const ORDERS = ["XYZ", "YXZ", "ZXY", "ZYX", "YZX", "XZY"];

// ───────────────────────────── seeded random inputs ─────────────────────────────
// Hand-picked values (axis-aligned, integer, symmetric) leave many terms of the formulas multiplied by zero or by one, so a
// wrong sign or operand in them goes unnoticed. These builders add dense, asymmetric, deterministic inputs: every builder is
// a pure function of its seed, so three.js and the compat layer receive identical numbers.
const prng = (seed) => {
  let t = seed >>> 0;
  return () => {
    t = (t + 0x6d2b79f5) >>> 0;
    let x = Math.imul(t ^ (t >>> 15), 1 | t);
    x ^= x + Math.imul(x ^ (x >>> 7), 61 | x);
    return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
  };
};
const rr = (r, lo, hi) => lo + (hi - lo) * r();
const rv2 = (seed, s = 4) => (L) => { const r = prng(seed); return new L.Vector2(rr(r, -s, s), rr(r, -s, s)); };
const rv3 = (seed, s = 4) => (L) => { const r = prng(seed); return new L.Vector3(rr(r, -s, s), rr(r, -s, s), rr(r, -s, s)); };
const rv4 = (seed, s = 4) => (L) => { const r = prng(seed); return new L.Vector4(rr(r, -s, s), rr(r, -s, s), rr(r, -s, s), rr(r, -s, s)); };
const runit = (seed) => (L) => rv3(seed, 1)(L).addScalar(0.01).normalize();
const rq = (seed) => (L) => { const r = prng(seed); return new L.Quaternion(rr(r, -1, 1), rr(r, -1, 1), rr(r, -1, 1), rr(r, -1, 1)).normalize(); };
const rm3 = (seed) => (L) => { const r = prng(seed); return new L.Matrix3().set(...Array.from({ length: 9 }, (_, i) => rr(r, -2, 2) + (i % 4 === 0 ? 2.5 : 0))); };
const rm4 = (seed) => (L) => { const r = prng(seed); return new L.Matrix4().set(...Array.from({ length: 16 }, (_, i) => rr(r, -2, 2) + (i % 5 === 0 ? 2.5 : 0))); };
const rm4aff = (seed) => (L) => new L.Matrix4().compose(rv3(seed)(L), rq(seed + 1)(L), rv3(seed + 2, 1.5)(L).addScalar(2));
const rrot = (seed) => (L) => { const r = prng(seed); return new L.Matrix4().makeRotationAxis(runit(seed + 1000)(L), rr(r, 0.2, 3.0)); };
const rrotPi = (seed) => (L) => new L.Matrix4().makeRotationAxis(runit(seed + 2000)(L), Math.PI);
const rcol = (seed) => (L) => { const r = prng(seed); return new L.Color().setRGB(r(), r(), r()); };
const reul = (seed) => (L) => { const r = prng(seed); return new L.Euler(rr(r, -3, 3), rr(r, -3, 3), rr(r, -3, 3), ORDERS[seed % 6]); };
const rbox = (seed) => (L) => { const r = prng(seed); const lo = new L.Vector3(rr(r, -3, 1), rr(r, -3, 1), rr(r, -3, 1)); return new L.Box3(lo, lo.clone().add(new L.Vector3(rr(r, 0.2, 4), rr(r, 0.2, 4), rr(r, 0.2, 4)))); };
const rsph = (seed) => (L) => { const r = prng(seed); return new L.Sphere(new L.Vector3(rr(r, -3, 3), rr(r, -3, 3), rr(r, -3, 3)), rr(r, 0.3, 3)); };
const rpln = (seed) => (L) => { const r = prng(seed); return new L.Plane(runit(seed + 500)(L), rr(r, -4, 4)); };
const rray = (seed) => (L) => new L.Ray(rv3(seed, 5)(L), runit(seed + 700)(L));
const rtri = (seed) => (L) => new L.Triangle(rv3(seed, 3)(L), rv3(seed + 31, 3)(L), rv3(seed + 62, 3)(L));
const seeds = (n, fn, base = 100) => Array.from({ length: n }, (_, i) => fn(base + i));
// a point on/near the receiver ray, so random shapes placed around it actually get hit
const nearRay = (seed, spread = 1.5) => (L, ray) => { const r = prng(seed); return ray.at(rr(r, 0, 8), new L.Vector3()).add(rv3(seed + 5, spread)(L)); };
const nearRayTri = (seed) => (L, ray) => { const c = nearRay(seed)(L, ray); return [c.clone().add(rv3(seed + 1, 1.5)(L)), c.clone().add(rv3(seed + 2, 1.5)(L)), c.clone().add(rv3(seed + 3, 1.5)(L))]; };
const nearRaySphere = (seed) => (L, ray) => new L.Sphere(nearRay(seed)(L, ray), 0.2 + prng(seed + 9)() * 1.8);
const nearRayBox = (seed) => (L, ray) => { const c = nearRay(seed)(L, ray); return new L.Box3(c.clone().addScalar(-0.5 - prng(seed + 3)()), c.clone().add(rv3(seed + 4, 1)(L).addScalar(1.5))); };
const nearRayPlane = (seed) => (L, ray) => { const c = nearRay(seed)(L, ray); const n = runit(seed + 50)(L); return new L.Plane(n, -n.dot(c)); };
const rlineOf = (seed) => (L) => { const start = rv3(seed, 4)(L); const end = rv3(seed + 70, 4)(L); return { start, end, delta: (target) => target.subVectors(end, start) }; };
const asymProj = (L) => new L.Matrix4().makePerspective(-0.4, 1.3, 0.9, -0.3, 0.2, 60);
const viewProj = (L) => new L.Matrix4().multiplyMatrices(asymProj(L), new L.Matrix4().compose(new L.Vector3(0.5, -0.2, -1), new L.Quaternion().setFromEuler(new L.Euler(0.2, -0.3, 0.1)), new L.Vector3(1, 1, 1)).invert());
// isMesh is false but getVertexPosition exists: the precise path must read the position attribute, never getVertexPosition
const objectNonMesh = (L) => {
  const pos = [[-2, -1, 0], [1, 3, 2], [0.5, 1, -3]];
  const attribute = { count: 3, getX: (i) => pos[i][0], getY: (i) => pos[i][1], getZ: (i) => pos[i][2] };
  return {
    updateWorldMatrix() {},
    geometry: { boundingBox: new L.Box3(new L.Vector3(-2, -1, -3), new L.Vector3(1, 3, 2)), getAttribute: () => attribute, computeBoundingBox() {} },
    matrixWorld: m4a(L),
    children: [],
    isMesh: false,
    getVertexPosition(i, target) { return target.set(99, 99, 99); },
  };
};
const rFrustum = (L) => [new L.Frustum().setFromProjectionMatrix(asymProj(L)), new L.Frustum().setFromProjectionMatrix(viewProj(L))];

// points exactly on the receiver's vertices, edge midpoints and centroid (Voronoi-region and containment boundaries)
const trianglePoints = [
  (L, t) => t.a.clone(), (L, t) => t.b.clone(), (L, t) => t.c.clone(),
  (L, t) => t.a.clone().add(t.b).multiplyScalar(0.5), (L, t) => t.b.clone().add(t.c).multiplyScalar(0.5), (L, t) => t.a.clone().add(t.c).multiplyScalar(0.5),
  (L, t) => t.a.clone().add(t.b).add(t.c).multiplyScalar(1 / 3),
];
// the receiver box's corners and face centres
const boxPoints = [
  (L, b) => b.min.clone(), (L, b) => b.max.clone(), (L, b) => b.getCenter(new L.Vector3()),
  (L, b) => new L.Vector3(b.min.x, b.max.y, b.min.z), (L, b) => new L.Vector3(b.max.x, b.min.y, b.max.z),
];
// planes passing exactly through the receiver box's low and high corners along each axis
const boxCornerPlanes = [
  (L, b) => new L.Plane(new L.Vector3(0, 1, 0), -b.min.y), (L, b) => new L.Plane(new L.Vector3(0, 1, 0), -b.max.y),
  (L, b) => new L.Plane(new L.Vector3(1, 0, 0), -b.min.x), (L, b) => new L.Plane(new L.Vector3(0, 0, 1), -b.max.z),
  (L, b) => new L.Plane(new L.Vector3(0, -1, 0), b.min.y), (L, b) => new L.Plane(new L.Vector3(-1, 0, 0), b.max.x),
];
const spherePoints = [
  (L, s) => s.center.clone().add(new L.Vector3(s.radius, 0, 0)), (L, s) => s.center.clone().add(new L.Vector3(0, -s.radius, 0)),
  (L, s) => s.center.clone(), (L, s) => s.center.clone().add(new L.Vector3(0, 0, s.radius * 2)),
];

/** Extra receiver variants per class (random, dense, asymmetric). */
const RX = {
  Vector2: [rv2(11), rv2(12)],
  Vector3: [rv3(11), rv3(12)],
  Vector4: [rv4(11), rv4(12)],
  Matrix3: [rm3(11), rm3(12)],
  Matrix4: [rm4(11), rm4(12), rm4aff(13), rm4aff(14)],
  Quaternion: [rq(11), rq(12)],
  Euler: [reul(11), reul(12), reul(13), reul(14), reul(15), reul(16)],
  Color: [
    rcol(11), rcol(12), rcol(13), rcol(14), (L) => new L.Color(1, 0, 0), (L) => new L.Color(0, 1, 0), (L) => new L.Color(0, 0, 1), (L) => new L.Color(0.5, 0.5, 0.5),
    (L) => new L.Color(0.04045, 0.0031308, 0.5), (L) => new L.Color(0.75, 0.25, 0.25),
  ],
  Box3: [rbox(11), rbox(12)],
  Sphere: [rsph(11), rsph(12)],
  Plane: [rpln(11), rpln(12)],
  Ray: [rray(11), rray(12), rray(13), rray(14)],
  Triangle: [rtri(11), rtri(12), rtri(13)],
  Frustum: [(L) => rFrustum(L)[0], (L) => rFrustum(L)[1]],
};

