/** `{ "Class#method": (L) => numbers }` for each spec entry, each argument set run against each receiver variant. */
const table = (cls, receivers, spec, extra = {}) => {
  const out = {};
  const allReceivers = (L) => [...receivers(L), ...(RX[cls] ?? []).map((make) => make(L))];
  const fuzz = FUZZ[cls] ?? {};
  for (const method of new Set([...Object.keys(spec), ...Object.keys(fuzz)])) {
    const argSets = [...(spec[method] ?? []), ...(fuzz[method] ?? [])];
    out[`${cls}#${method}`] = (L) => argSets.flatMap((argsOf) => allReceivers(L).flatMap((r) => run(L, r, method, argsOf)));
  }
  for (const [name, fn] of Object.entries(extra)) out[`${cls}#${name}`] = fn;
  return out;
};

