  setFromArray: [A(arr(0, 1, 2, -3, 4, 5, 6, -7, 8)), A(arr())],
  setFromBufferAttribute: [A(attr)],
  setFromPoints: [A((L) => [new L.Vector3(0, 0, 0), new L.Vector3(7, 1, 2), new L.Vector3(-3, 9, 1)]), A(arr())],
  setFromCenterAndSize: [A(v3(1, 2, 3), v3(2, 4, 6))],
  setFromObject: [A(objectOf), A(objectOf, true), A(lazyBoxObject)],
  clone: [A()],
  copy: [A(box(0, 0, 0, 1, 1, 1)), A(SELF)],
  makeEmpty: [A()],
  isEmpty: [A()],
  getCenter: [A(v3())],
  getSize: [A(v3())],
  expandByPoint: [A(v3(9, -9, 0)), A(v3(0, 0, 0))],
  expandByVector: [A(v3(1, 2, 3))],
  expandByScalar: [A(0.5), A(-3)],
  expandByObject: [A(objectOf), A(objectOf, true), A(lazyBoxObject)],
  containsPoint: [A(v3(0, 0, 0)), A(v3(4, 5, 6)), A(v3(9, 0, 0))],
  containsBox: [A(box(0, 0, 0, 1, 1, 1)), A(box(-2, 0, 0, 1, 1, 1)), A(SELF)],
  getParameter: [A(v3(1, 1, 1), v3())],
  intersectsBox: [A(box(0, 0, 0, 1, 1, 1)), A(box(10, 10, 10, 11, 11, 11)), A(SELF)],
  intersectsSphere: [A(sph(0, 0, 0, 1)), A(sph(20, 0, 0, 1)), A(sph(4.5, 5, 6, 0.6))],
  intersectsPlane: [A(pln(0, 1, 0, 0)), A(pln(1, 0, 0, -10)), A(pln(0, -1, 0, 3)), A(pln(1, 1, 1, 0))],
  intersectsTriangle: trisFor.map((t) => A(t)),
  clampPoint: [A(v3(9, -9, 0), v3()), A(v3(0, 0, 0), v3())],
  distanceToPoint: [A(v3(10, 0, 0)), A(v3(0, 0, 0))],
  getBoundingSphere: [A((L) => new L.Sphere())],
  intersect: [A(box(0, 0, 0, 1, 1, 1)), A(box(10, 10, 10, 11, 11, 11)), A(SELF)],
  union: [A(box(0, 0, 0, 10, 1, 1)), A(SELF), A((L) => new L.Box3())],
  applyMatrix4: [A((L) => new L.Matrix4().makeRotationZ(0.6)), A(m4a), A(m4p)],
