  intersectLine: [
    A(lineOf(0, 0, 0, 0, 5, 0), v3()), A(lineOf(0, 0, 0, 0, 1, 0), v3()), A(lineOf(0, 0, 0, 0, 1, 0), v3(), false), A(lineOf(0, 0, 0, 5, 0, 0), v3()),
    A(lineOf(0, 2, 0, 5, 2, 0), v3()), A(lineOf(0, -5, 0, 0, 5, 0), v3()),
  ],
  intersectsLine: [A(lineOf(0, 0, 0, 0, 5, 0)), A(lineOf(0, 0, 0, 0, 1, 0)), A(lineOf(0, 5, 0, 0, 0, 0))],
  intersectsBox: [A(box(-1, -1, -1, 1, 3, 1)), A(box(10, 10, 10, 11, 11, 11))],
  intersectsSphere: [A(sph(0, 2, 0, 1)), A(sph(0, 20, 0, 1))],
  coplanarPoint: [A(v3())],
  applyMatrix4: [A(m4a), A((L) => new L.Matrix4().makeRotationX(0.5)), A(m4a, m3a)],
  translate: [A(v3(1, 2, 3))],
  equals: [A(pln(0, 1, 0, -2)), A(pln(0, 1, 0, 3)), A(SELF)],
  clone: [A()],
